-- # Lernfeld 5: Cyberphysische Systeme > ## Testgetriebene Entwicklung > - Werkzeuge > - Continuous Integration (CI)-Systeme

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist ein Continuous Integration (CI)-System in der testgetriebenen Entwicklung (TDD) notwendig, um Tests automatisch auszuführen?', 2, '[{"text": "Ja", "correct": true, "because": "CI automatisiert Testausführung"}, {"text": "Nein", "correct": false, "because": "Manuelle Ausführung ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Können CI-Systeme in TDD ohne Versionskontrolle wie Git effektiv arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Versionskontrolle ist CI-Grundlage"}, {"text": "Ja", "correct": false, "because": "Integration braucht Repository"}]'),
('00000000-0000-0000-0000-000000000000', 'Erfordern CI-Systeme in TDD immer eine Cloud-basierte Infrastruktur?', 2, '[{"text": "Nein", "correct": true, "because": "Lokale Server möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Können CI-Systeme in TDD die Qualität der Software garantieren?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität hängt von Tests ab"}, {"text": "Ja", "correct": false, "because": "Nur Werkzeug, keine Garantie"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Integration von CI-Systemen in TDD mit einem hohen Anfangsinvest verbunden?', 2, '[{"text": "Ja", "correct": true, "because": "Einrichtung erfordert Zeit"}, {"text": "Nein", "correct": false, "because": "Aufwand real"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Hauptfunktion hat ein CI-System in TDD?', 2, '[{"text": "Automatisierte Testausführung", "correct": true, "because": "Kernaufgabe von CI"}, {"text": "Code-Optimierung", "correct": false, "because": "Nicht primär"}, {"text": "Dokumentation", "correct": false, "because": "Nebenprodukt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches CI-System ist besonders für Open-Source-Projekte auf GitHub beliebt?', 3, '[{"text": "Travis CI", "correct": true, "because": "Weit verbreitet bei GitHub"}, {"text": "Jenkins", "correct": false, "because": "Eher lokal"}, {"text": "CircleCI", "correct": false, "because": "Auch beliebt, aber breiter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil eines CI-Systems ist in TDD am bedeutendsten?', 2, '[{"text": "Schnelle Rückmeldung", "correct": true, "because": "Fördert schnelle Iterationen"}, {"text": "Kostenreduktion", "correct": false, "because": "Sekundär"}, {"text": "Manuelle Tests", "correct": false, "because": "Automatisierung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein CI-System im Red-Green-Refactor-Zyklus?', 2, '[{"text": "Automatische Validierung", "correct": true, "because": "Prüft Tests in jedem Schritt"}, {"text": "Code-Generierung", "correct": false, "because": "Nicht Aufgabe"}, {"text": "Fehlerbehebung", "correct": false, "because": "Entwickleraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature eines CI-Systems ist für TDD unerlässlich?', 2, '[{"text": "Automatisierte Builds", "correct": true, "because": "Sichert Integration"}, {"text": "Manuelle Überprüfung", "correct": false, "because": "Ineffizient"}, {"text": "Dokumentengenerierung", "correct": false, "because": "Sekundär"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt ein CI-System in TDD?', 4, '[{"text": "Automatisierte Testausführung", "correct": true, "because": "Prüft Code"}, {"text": "Code-Builds", "correct": true, "because": "Erstellt lauffähigen Code"}, {"text": "Manuelle Fehlerbehebung", "correct": false, "because": "Entwickleraufgabe"}, {"text": "Integrationsüberprüfung", "correct": true, "because": "Sichert Zusammenführung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein CI-System in TDD?', 3, '[{"text": "Schnelle Fehlererkennung", "correct": true, "because": "Tests laufen sofort"}, {"text": "Kontinuierliche Validierung", "correct": true, "because": "Jeder Commit geprüft"}, {"text": "Langsamere Entwicklung", "correct": false, "because": "Beschleunigt"}, {"text": "Verbesserte Teamproduktivität", "correct": true, "because": "Automatisierung hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche CI-Systeme sind für TDD geeignet?', 3, '[{"text": "Jenkins", "correct": true, "because": "Flexibel und lokal"}, {"text": "Travis CI", "correct": true, "because": "GitHub-Integration"}, {"text": "Microsoft Word", "correct": false, "because": "Kein CI-Tool"}, {"text": "GitHub Actions", "correct": true, "because": "Modern und integriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei CI-Systemen in TDD?', 4, '[{"text": "Hoher Einrichtungsaufwand", "correct": true, "because": "Initiale Konfiguration"}, {"text": "Wartung der Pipeline", "correct": true, "because": "Änderungen nötig"}, {"text": "Keine Automatisierung", "correct": false, "because": "Automatisierung zentral"}, {"text": "Komplexität bei Skalierung", "correct": true, "because": "Große Projekte schwierig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für CI-Systeme in TDD wichtig?', 3, '[{"text": "Versionskontrolle", "correct": true, "because": "Repository nötig"}, {"text": "Automatisierte Tests", "correct": true, "because": "Validierung"}, {"text": "Manuelle Builds", "correct": false, "because": "Automatisierung zentral"}, {"text": "Build-Skripte", "correct": true, "because": "Erstellung automatisiert"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) CI-Systeme in TDD automatisieren Tests. b) CI-Systeme ersetzen Entwickler bei der Fehlerbehebung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests automatisiert, Behebung manuell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CI-Systeme in TDD benötigen Versionskontrolle. b) CI-Systeme sind in TDD optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Versionskontrolle nötig, CI zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) CI-Systeme in TDD beschleunigen die Entwicklung. b) CI-Systeme garantieren fehlerfreien Code.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Beschleunigung real, keine Garantie"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) CI-Systeme in TDD können lokal betrieben werden. b) CI-Systeme machen Tests überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lokal möglich, Tests zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) CI-Systeme unterstützen den Red-Green-Refactor-Zyklus. b) CI-Systeme erfordern keine Wartung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zyklus unterstützt, Wartung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

